const int MAXN = (int)3e5 + 5;

int a[MAXN];
int b[MAXN];
int n;

pair<int, int> t[MAXN * 2];
int e[MAXN * 2];

void build(int v = 1, int tl = 1, int tr = n) {
  t[v] = {0, tr - tl + 1};
  e[v] = 0;

   if (tl != tr) {

        build(c1, tl, mid);
        build(c2, mid + 1, tr);
    }
}

void push(int v, int tl, int tr) {
  if (e[v]) {
      t[v].first += e[v];

        if (tl != tr) {

            e[c1] += e[v];
            e[c2] += e[v];
        }

        e[v] = 0;
    }
}

pair<int, int> comb(pair<int, int> a, pair<int, int> b) {
  if (a.first == b.first) {
      return mp(a.first, a.second + b.second);
  }

    return max(a, b);
}

void update(int l, int r, int x, int v = 1, int tl = 1, int tr = n) {
  push(v, tl, tr);

    if (l > r || tl > r || tr < l) {
        return;
    }

    if (l <= tl && tr <= r) {
        e[v] += x;
        push(v, tl, tr);
        return;
    }

    update(l, r, x, c1, tl, mid);
    update(l, r, x, c2, mid + 1, tr);

    t[v] = comb(t[c1], t[c2]);
}

int query() {
   push(1, 1, n);
   return t[1].first == 2 ? t[1].second : 0;
}

int main() {
   ios::sync_with_stdio(0);
   cin.tie(0);

    cin >> n;

       cin >> a[i];
       b[i] = i;
    }

    sort(b + 1, b + n + 1, [&](int i, int j) -> bool {
        return mp(a[i], i) > mp(a[j], j);
    });

    vector<array<int, 5>> rectangles;

    for (int step = 0; step < 2; step++) {
       set<int> S{0, n+1};

          int pos = b[i];
          auto it = S.insert(pos).first;

          if (*prev(it) > 0) {
              int lx = *prev(it, 2) + 1;
              int rx = *prev(it);

              int ly = *it;
              int ry = *next(it) - 1;

              int val = abs(a[*prev(it)] - a[pos]);

              rectangles.pb({val, lx, rx, ly, ry});
          }

          if (*next(it) <= n) {

            int lx = *prev(it) + 1;
            int rx = *it;

            int ly = *next(it);
            int ry = *next(it, 2) - 1;

            int val = abs(a[*next(it)] - a[pos]);

            rectangles.pb({val, lx, rx, ly, ry});
        }
    }

    reverse(b + 1, b + n + 1);
}

ll ans = 0;

build();
sort(all(rectangles));
vector<array<int, 4>> ev;

for (int l = 0, r; l < sz(rectangles); l = r) {
   ev.clear();
   r = l;

    while (r < sz(rectangles) && rectangles[l][0] == rectangles[r][0]) {
      int lx = rectangles[r][1], rx = rectangles[r][2];
      int ly = rectangles[r][3], ry = rectangles[r][4];

        ev.pb({lx, 1, ly, ry});
        ev.pb({rx + 1, -1, ly, ry});

        r++;
    }

    sort(all(ev));
    int lst = -1;

    for (auto [x, val, l, r] : ev) {
       if (lst != -1 && x != lst) {
           ans += query() * 1ll * (x - lst);
       }

        lst = x;
        update(l, r, val);
    }
}

    cout << ans << '\n';
    cerr << (double)clock() / CLOCKS_PER_SEC << endl;
    return 0;
}

