void solve() {
  scanf("%d%d", &n, &k);

       scanf("%d", &c[i]);
       scanf("%d", &was[i]);

    int mx = get(inf).s;
    int mn = get(-inf).s;

    if(k < mn || k > mx){
        printf("-1\n");
        return;
    }

    int l = -inf, r = inf;
    while(l <= r){
       int mid = (l + r) >> 1;

        if(get(mid).s <= k) l = mid + 1;
        else r = mid - 1;
    }

    int pen = l - 1;
    pair<ll, int> cur = get(pen);
    ll res = 0;

    if(cur.s == k){
        res = cur.f - k * 1ll * pen;
    }else{
        pair<ll, int> nxt = get(pen + 1);

        ll val1 = get(nxt, l), val2 = get(cur, l - 1);
        ll tot = val1 - val2;
        int delta = (nxt.s - cur.s);
        assert(delta != 0);

        ll d = tot / delta;
        res = d * (k - cur.s) + val2;
    }

    printf("%lld\n", res);
}

main () {
  int TT;
  TT = 1;
  for (int tt = 1; tt <= TT; ++tt) {
     solve();
  }
}

